values ('bbbb0004-0000-4000-8000-000000000011', 'en', null, 'Genetics', 'How traits are stored in DNA, copied, shuffled by meiosis, and passed on — from Mendel''s peas to CRISPR. Structure adapted from the Genetics unit of OpenStax Biology 2e (CC BY 4.0).', null, 'foundations', 17, true, 'science', '{bbbb0004-0000-4000-8000-000000000001}')
