insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-000000000011', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"DNA''s double helix is held together by base pairs. Adenine (A) always pairs with…","options":["guanine (G)","cytosine (C)","thymine (T)","another adenine (A)"],"answer":2,"explanation":"A pairs with T, and G pairs with C — see ''DNA structure & replication''."},{"prompt":"A gene is best described as…","options":["a whole chromosome","a segment of DNA that codes for a product","a type of protein","a single base pair"],"answer":1,"explanation":"A gene is a stretch of DNA carrying instructions for a product — see ''Genes, chromosomes & mutations''."},{"prompt":"In a cross of two heterozygotes (Aa × Aa), the phenotype ratio of dominant to recessive is…","options":["1:1","3:1","9:1","1:2:1"],"answer":1,"explanation":"A monohybrid Aa × Aa cross gives a 3:1 phenotype ratio — see ''Mendelian inheritance''."},{"prompt":"Meiosis produces gametes that are…","options":["diploid, like the parent cell","haploid, with half the chromosome number","identical to the parent cell","polyploid"],"answer":1,"explanation":"Meiosis halves the chromosome number to make haploid gametes — see ''Meiosis & genetic variation''."},{"prompt":"During protein synthesis, DNA is first copied into…","options":["another DNA strand","messenger RNA (mRNA)","an amino acid","a ribosome"],"answer":1,"explanation":"Transcription copies DNA into mRNA — see ''Transcription & translation''."},{"prompt":"In RNA, which base replaces thymine (T)?","options":["uracil (U)","guanine (G)","adenine (A)","cytosine (C)"],"answer":0,"explanation":"RNA uses uracil (U) instead of thymine — see ''Transcription & translation''."},{"prompt":"A homozygous individual for a gene carries…","options":["two different alleles","two identical alleles","only one allele total","no alleles"],"answer":1,"explanation":"Homozygous = two identical alleles (e.g. AA or aa) — see ''Mendelian inheritance''."},{"prompt":"CRISPR-Cas9 is primarily a tool for…","options":["sequencing whole genomes only","editing specific DNA sequences","growing bacteria","copying RNA into protein"],"answer":1,"explanation":"CRISPR-Cas9 targets and edits specific DNA sequences — modern genetics & biotechnology."}]}'::jsonb, null, 10),
  (2, 'DNA structure and how it copies itself', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe the structure of DNA and explain why replication is called *semiconservative*. Warm-up: from the diagnostic, which base pairs with adenine?"},{"heading":"The idea","text":"DNA is a *double helix*: two strands twisted together. Each strand is a chain of *nucleotides*, and each nucleotide has a sugar, a phosphate, and one of four *bases* — adenine (A), thymine (T), guanine (G), cytosine (C). The two strands are held together by base pairing: A always pairs with T, and G always pairs with C. The strands are *antiparallel* — one runs 5′→3′ while its partner runs 3′→5′. Because each base specifies its partner, one strand is a template for rebuilding the other. That is the whole trick of heredity."},{"heading":"Worked example","text":"Replication is *semiconservative*: each new double helix keeps one old strand and one new strand. First, the enzyme *helicase* unwinds the helix; then *DNA polymerase* reads each template and adds complementary nucleotides in the 5′→3′ direction. Take the template strand 3′-T A C G G A-5′. Reading the pairing rule (A↔T, G↔C), the new strand is 5′-A T G C C T-3′. Notice every A on the template drew a T, and every G drew a C."},{"heading":"Your turn","text":"Write the complementary strand for each template. (1) 3′-A A T C-5′ (2) 3′-G C G T-5′ (3) 3′-T T A C G-5′ (4) 3′-C A T G-5′. Answers: (1) 5′-T T A G-3′; (2) 5′-C G C A-3′; (3) 5′-A A T G C-3′; (4) 5′-G T A C-3′."},{"heading":"Common mistakes & exit ticket","text":"Mistake: pairing A with G or C (only A–T and G–C are allowed). Mistake: thinking both strands are newly built — one is always inherited (that''s what ''semiconservative'' means). Exit: (a) What pairs with cytosine? (b) After replication, how many original strands are in each new double helix? Answers: guanine; one."}]}'::jsonb, 'Base-pairing rule: A–T and G–C. Strands run antiparallel (5′→3′ opposite 3′→5′).', 13),
  (3, 'Genes, chromosomes, and mutations', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how genes sit on chromosomes and how mutations change them. Warm-up: what do we call one version of a gene?"},{"heading":"The idea","text":"A *gene* is a segment of DNA that carries instructions for a product, usually a protein. Genes are packaged, wound around proteins, into *chromosomes*. Humans have 46 chromosomes arranged in 23 *homologous pairs* — one of each pair from each parent. Because you inherit a pair, you carry two copies of most genes; different versions of a gene are called *alleles*. A *mutation* is a change in the DNA sequence. A *point mutation* swaps a single base (a substitution); *insertions* or *deletions* add or remove bases and can shift the whole reading frame (a *frameshift*)."},{"heading":"Worked example","text":"Sickle-cell disease comes from a single point mutation in the beta-globin gene: the DNA codon changes from GAG to GTG. That one-base swap changes the amino acid from glutamic acid to valine, and the altered protein makes red blood cells stiffen into a sickle shape. One base out of billions — a big effect. Contrast that with a *silent* mutation, where the base change still codes for the same amino acid and nothing changes."},{"heading":"Your turn","text":"Classify each mutation. (1) A T→C substitution that still codes for the same amino acid. (2) One base removed, shifting everything downstream. (3) A change from a normal codon to a stop codon. (4) A single base swapped for another, changing one amino acid. Answers: (1) silent point mutation; (2) frameshift (deletion); (3) nonsense mutation; (4) missense point mutation."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking a gene and a chromosome are the same size (a chromosome holds many genes). Mistake: assuming every mutation is harmful — many are silent or even helpful. Exit: (a) How many chromosome pairs do humans have? (b) What is a frameshift caused by? Answers: 23 pairs; an insertion or deletion of bases."}]}'::jsonb, 'Gene = a stretch of DNA. Allele = one version of a gene. Humans: 46 chromosomes (23 pairs).', 12),
  (4, 'Mendelian inheritance and Punnett squares', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Use a Punnett square to predict offspring ratios and state Mendel''s two laws. Warm-up: what ratio do you expect from crossing two heterozygotes?"},{"heading":"The idea","text":"Mendel found that traits are passed as discrete units (now called *genes*). Each parent carries two *alleles* and passes one to each offspring — the *law of segregation*. A *dominant* allele (written with a capital, e.g. A) masks a *recessive* one (lowercase, a). *Homozygous* means two identical alleles (AA or aa); *heterozygous* means two different ones (Aa). A *Punnett square* lists each parent''s possible gametes on the two sides and fills the boxes with the offspring combinations."},{"heading":"Worked example","text":"Cross two heterozygous tall pea plants, Aa × Aa. Each parent makes A and a gametes. The 2×2 square gives: AA, Aa, Aa, aa. Genotype ratio 1 AA : 2 Aa : 1 aa. Since A is dominant, AA, Aa, and Aa are all tall and only aa is short — a phenotype ratio of 3 tall : 1 short, i.e. 3:1. Now a *dihybrid* cross, AaBb × AaBb, follows the *law of independent assortment* (genes on different chromosomes sort independently). Its 4×4 square yields the classic 9:3:3:1 phenotype ratio — 9 showing both dominant traits, 3 and 3 showing one each, 1 showing both recessive."},{"heading":"Your turn","text":"(1) In Aa × Aa, what fraction of offspring are homozygous recessive? (2) Cross a heterozygote with a homozygous recessive (Aa × aa) — what is the phenotype ratio? (3) In the 9:3:3:1 dihybrid result, how many of 16 boxes show both recessive traits? (4) Two brown-eyed parents (Bb × Bb) have a blue-eyed child (bb) — was that possible? Answers: (1) 1/4; (2) 1:1 (half dominant, half recessive); (3) 1 of 16; (4) yes — each parent can pass the recessive b."},{"heading":"Common mistakes & exit ticket","text":"Mistake: writing the offspring ratio as the genotype ratio (1:2:1) when the question asks for phenotype (3:1). Mistake: thinking two dominant-looking parents can''t have a recessive child (Aa × Aa can). Exit: (a) Phenotype ratio of Aa × Aa? (b) Which law explains the 9:3:3:1 result? Answers: 3:1; the law of independent assortment."}]}'::jsonb, 'Dominant allele = capital letter; recessive = lowercase. Genotype = the alleles; phenotype = the visible trait.', 14),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"In DNA, guanine (G) always pairs with…","options":["adenine","thymine","cytosine","uracil"],"answer":2,"explanation":"G pairs with C."},{"prompt":"''Semiconservative'' replication means each new double helix contains…","options":["two new strands","two old strands","one old and one new strand","only RNA"],"answer":2,"explanation":"One template strand is conserved, one is newly made."},{"prompt":"A frameshift mutation is caused by…","options":["a single base substitution","an insertion or deletion of bases","unwinding the helix","base pairing"],"answer":1,"explanation":"Adding or removing bases shifts the reading frame."},{"prompt":"The genotype Aa is described as…","options":["homozygous dominant","homozygous recessive","heterozygous","haploid"],"answer":2,"explanation":"Two different alleles = heterozygous."},{"prompt":"Crossing Aa × Aa gives a phenotype ratio of…","options":["1:1","1:2:1","3:1","9:3:3:1"],"answer":2,"explanation":"3 dominant : 1 recessive."},{"prompt":"A dihybrid cross AaBb × AaBb produces a phenotype ratio of…","options":["3:1","1:1","9:3:3:1","1:2:1"],"answer":2,"explanation":"The classic 9:3:3:1 from independent assortment."}]}'::jsonb, null, 8),
  (6, 'Meiosis and the sources of genetic variation', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how meiosis halves the chromosome number and creates variation. Warm-up: are gametes haploid or diploid?"},{"heading":"The idea","text":"Body cells are *diploid* (2n): they carry two of each chromosome. To make gametes (eggs and sperm), a cell runs *meiosis* — two rounds of division that produce four *haploid* (n) cells, each with a single set of chromosomes. In humans that means going from 46 chromosomes to 23. When a sperm and egg fuse at fertilization, the diploid number is restored. Two features of meiosis generate variation: *crossing over*, where homologous chromosomes swap segments during prophase I, and the *independent assortment* of homologous pairs during metaphase I."},{"heading":"Worked example","text":"Consider independent assortment alone. Each of the 23 human chromosome pairs lines up and sorts independently, so the number of possible gamete combinations is 2^23 ≈ 8.4 million — before crossing over adds even more. That is why siblings differ. Contrast meiosis with *mitosis*, which makes two identical diploid cells for growth and repair; meiosis instead makes four genetically unique haploid cells."},{"heading":"Your turn","text":"(1) How many haploid cells does one meiosis produce? (2) If a diploid cell has 2n = 8, how many chromosomes are in each gamete? (3) In which phase does crossing over occur? (4) Does mitosis or meiosis create genetic variation? Answers: (1) four; (2) 4; (3) prophase I; (4) meiosis."},{"heading":"Common mistakes & exit ticket","text":"Mistake: confusing meiosis with mitosis (mitosis = two identical diploid cells; meiosis = four varied haploid cells). Mistake: thinking gametes are diploid. Exit: (a) From 46 chromosomes, how many does a human gamete carry? (b) Name one source of variation in meiosis. Answers: 23; crossing over (or independent assortment)."}]}'::jsonb, 'Diploid (2n) → meiosis → four haploid (n) gametes. Crossing over happens in prophase I.', 13),
  (7, 'Transcription and translation: reading the code', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Trace how a gene becomes a protein through transcription and translation. Warm-up: which base replaces thymine in RNA?"},{"heading":"The idea","text":"The *central dogma* is DNA → RNA → protein. In *transcription*, the enzyme RNA polymerase reads a DNA template and builds a matching *messenger RNA (mRNA)* strand — but RNA uses *uracil (U)* wherever DNA would use thymine. In *translation*, a *ribosome* reads the mRNA three bases at a time. Each triplet is a *codon* that specifies one amino acid, delivered by *tRNA*. Amino acids link into a protein. Reading starts at the *start codon* AUG (methionine) and ends at a *stop codon*."},{"heading":"Worked example","text":"Take the DNA template strand 3′-T A C-5′. Transcription pairs it (A↔U, T↔A, G↔C, C↔G) into the mRNA codon 5′-A U G-3′. Look up AUG in the genetic code: it is methionine, the start signal. Next take DNA template 3′-A A A-5′ → mRNA 5′-U U U-3′ → phenylalanine. So the template 3′-TAC-AAA-5′ produces the mRNA AUG-UUU and the peptide Met–Phe."},{"heading":"Your turn","text":"(1) In RNA, what pairs with adenine? (2) How many bases make one codon? (3) Transcribe the DNA template 3′-T A C-5′ into mRNA. (4) What amino acid does the codon AUG specify? Answers: (1) uracil; (2) three; (3) 5′-A U G-3′; (4) methionine (the start)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: using thymine in RNA (RNA has uracil instead). Mistake: reading codons as two bases instead of three. Exit: (a) What does transcription produce? (b) How many bases in a codon? Answers: messenger RNA (mRNA); three."}]}'::jsonb, 'Central dogma: DNA → RNA → protein. A codon is three mRNA bases; AUG = start (methionine).', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"allele","translation":"one of the alternative versions of a gene","example":"The brown-eye and blue-eye alleles are versions of the same eye-color gene."},{"term":"genotype","translation":"the specific alleles an organism carries for a trait","example":"A plant with the genotype Aa is heterozygous."},{"term":"phenotype","translation":"the observable trait produced by the genotype","example":"The phenotype of an Aa pea plant is tall."},{"term":"homozygous","translation":"having two identical alleles for a gene (AA or aa)","example":"Only homozygous recessive (aa) plants are short."},{"term":"codon","translation":"a sequence of three mRNA bases that codes for one amino acid","example":"The codon AUG signals the start of translation and codes for methionine."},{"term":"meiosis","translation":"cell division that makes four haploid gametes from a diploid cell","example":"Meiosis halves the chromosome number, from 46 to 23 in humans."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"One round of meiosis produces…","options":["two identical diploid cells","four haploid cells","one haploid cell","two haploid cells"],"answer":1,"explanation":"Meiosis yields four haploid gametes."},{"prompt":"In RNA, adenine pairs with…","options":["thymine","uracil","guanine","cytosine"],"answer":1,"explanation":"RNA uses uracil in place of thymine."},{"prompt":"The central dogma of molecular biology is…","options":["protein → RNA → DNA","DNA → RNA → protein","RNA → DNA → protein","DNA → protein → RNA"],"answer":1,"explanation":"Information flows DNA → RNA → protein."},{"prompt":"The start codon AUG codes for the amino acid…","options":["glycine","valine","methionine","phenylalanine"],"answer":2,"explanation":"AUG codes for methionine and signals the start of translation."},{"prompt":"Crossing over, a source of variation, occurs during…","options":["prophase I of meiosis","mitosis","translation","DNA replication"],"answer":0,"explanation":"Homologous chromosomes swap segments in prophase I."},{"prompt":"A human gamete carries how many chromosomes?","options":["46","23","92","22"],"answer":1,"explanation":"Gametes are haploid: 23 chromosomes."}]}'::jsonb, null, 8),
  (10, 'Applied project: predict inheritance across generations', 'writing', '{"sections":[{"heading":"The task","text":"Choose a single-gene trait that follows simple dominant/recessive inheritance (for example: pea plant height, the ability to roll your tongue, or attached vs. free earlobes). You will predict how it is passed down across three generations using Punnett squares — no lab needed, just careful reasoning."},{"heading":"Milestones","text":"1) Define your trait and assign symbols (capital for dominant, lowercase for recessive). 2) Pick starting genotypes for two grandparents and cross them with a Punnett square; report the genotype and phenotype ratios. 3) Choose one offspring, give it a mate, and cross again to predict the grandchildren. 4) State the probability that a specific grandchild shows the recessive phenotype, and explain how a recessive trait can ''skip'' a generation."},{"heading":"Self-check rubric","text":"✔ Symbols and genotypes are defined clearly and used consistently. ✔ Each Punnett square is filled correctly and the ratios (e.g. 3:1 or 1:1) match the boxes. ✔ Probabilities are stated as fractions or percentages and are internally consistent. ✔ You correctly explained that a recessive allele can be carried by a heterozygote without showing, then reappear when two carriers meet. If all four hold, you''ve reasoned like a geneticist."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-000000000011' and l.position = v.pos
);
